1	#!/usr/bin/env node
2	// Prov Guard —— 软件供应链证明与完整性校验工具（零依赖，Node >= 18）。
3	//
4	// 子命令：
5	//   keygen   --key-dir <dir> [--name <prefix>]
6	//   generate --artifact <path> --key <private-key> --out <dir> [--bundle]
7	//   verify   --artifact <path> --proof <file> --signature <file> --key <public-key>
8	//            [--sbom <file> --sbom-signature <file>] [--policy <policy.json>]
9	//   verify   --artifact <path> --bundle <proof.bundle.json> --key <public-key>
10	//            [--cosigner-key <public-key> ... --min-cosigners <n>] [--policy <policy.json>]
11	//
12	// 所有输出均为 UTF-8；成功结果写 stdout，错误结果写 stderr。
13	
14	import {
15	  createHash,
16	  createPrivateKey,
17	  createPublicKey,
18	  generateKeyPairSync,
19	  sign as cryptoSign,
20	  verify as cryptoVerify,
21	} from 'node:crypto';
22	import { constants as fsConstants, readFileSync, realpathSync } from 'node:fs';
23	import { access, mkdir, readdir, readFile, realpath, rename, rm, stat, writeFile } from 'node:fs/promises';
24	import { basename, dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
25	import { fileURLToPath } from 'node:url';
26	
27	export const PROOF_VERSION = '1.0';
28	// 启用多方共签时证明版本升为 1.1；共签清单（proof/sbom.cosignatures.json）的 schemaVersion。
29	export const PROOF_VERSION_COSIGN = '1.1';
30	export const COSIGN_SCHEMA_VERSION = '1.0';
31	// 证明分发包（proof.bundle.json）版本与成员逻辑名。
32	export const BUNDLE_VERSION = '1.0';
33	export const BUNDLE_BASE_MEMBERS = Object.freeze(['proof', 'proof-signature', 'sbom', 'sbom-signature']);
34	export const BUNDLE_COSIGN_MEMBERS = Object.freeze(['proof-cosignatures', 'sbom-cosignatures']);
35	
36	// ---------------------------------------------------------------------------
37	// 错误类型：携带机器可读错误码，CLI 边界统一转换为非零退出。
38	// ---------------------------------------------------------------------------
39	
40	export const ERROR_CODES = Object.freeze({
41	  INPUT_NOT_FOUND: 'INPUT_NOT_FOUND',
42	  PERMISSION_DENIED: 'PERMISSION_DENIED',
43	  PROOF_INVALID: 'PROOF_INVALID',
44	  SIGNATURE_INVALID: 'SIGNATURE_INVALID',
45	  KEY_NOT_FOUND: 'KEY_NOT_FOUND',
46	  INTEGRITY_MISMATCH: 'INTEGRITY_MISMATCH',
47	  POLICY_INVALID: 'POLICY_INVALID',
48	  POLICY_VIOLATION: 'POLICY_VIOLATION',
49	  SYMLINK_INVALID: 'SYMLINK_INVALID',
50	  USAGE_ERROR: 'USAGE_ERROR',
51	});
52	
53	class ProvError extends Error {
54	  constructor(code, message, details) {
55	    super(message);
56	    this.name = 'ProvError';
57	    this.code = code;
58	    if (details !== undefined) this.details = details;
59	  }
60	}
61	
62	// 把 Node 底层错误归类为 INPUT_NOT_FOUND / PERMISSION_DENIED，其余原样抛出。
63	function wrapFsError(err, context) {
64	  if (err instanceof ProvError) return err;
65	  const where = context ? `${context}: ` : '';
66	  if (err && err.code === 'ENOENT') {
67	    return new ProvError(ERROR_CODES.INPUT_NOT_FOUND, `${where}路径不存在 (${err.path || 'unknown path'})`);
68	  }
69	  if (err && (err.code === 'EACCES' || err.code === 'EPERM')) {
70	    return new ProvError(ERROR_CODES.PERMISSION_DENIED, `${where}权限不足 (${err.path || 'unknown path'})`);
71	  }
72	  return err;
73	}
74	
75	// ---------------------------------------------------------------------------
76	// 路径与摘要工具
77	// ---------------------------------------------------------------------------
78	
79	// 清单中的相对路径统一使用正斜杠，保证跨平台稳定。
80	export function toPosix(relPath) {
81	  return relPath.split(sep).join('/');
82	}
83	
84	// 稳定哈希：SHA-256，摘要对象按 key 排序后以 UTF-8 序列化（两空格缩进）。
85	export function stableJsonStringify(value) {
86	  return JSON.stringify(sortDeep(value), null, 2);
87	}
88	
89	function sortDeep(value) {
90	  if (Array.isArray(value)) return value.map(sortDeep);
91	  if (value !== null && typeof value === 'object') {
92	    const out = {};
93	    for (const key of Object.keys(value).sort()) out[key] = sortDeep(value[key]);
94	    return out;
95	  }
96	  return value;
97	}
98	
99	export function sha256Hex(data) {
100	  return createHash('sha256').update(data).digest('hex');
101	}
102	
103	// 公钥指纹：对 SPKI 编码的 DER 字节取 SHA-256。写入证明并随证明一起签名，
104	// 验证时据此区分“使用了错误公钥”（指纹不一致）与“签名内容被篡改”（指纹一致但验签失败）。
105	export function keyFingerprint(keyObj) {
106	  return sha256Hex(keyObj.export({ type: 'spki', format: 'der' }));
107	}
108	
109	// ---------------------------------------------------------------------------
110	// 产物扫描：递归列出全部常规文件（含符号链接解引用后的目标），
111	// 空目录自然产生空清单；零字节文件按真实文件记录。
112	// 符号链接安全规则（按真实路径判定）：
113	//   - 目标越出产物根目录                 -> SYMLINK_INVALID / outside-root；
114	//   - 目标为当前递归祖先链上的目录（含根目录自身），或链接互相成环（ELOOP）
115	//                                        -> SYMLINK_INVALID / cycle；
116	//   - 指向根目录内部普通文件/目录的链接按链接路径记录目标内容；
117	//     祖先链之外的重复目标允许展开（有向无环，不会形成回路）。
118	// 判定在读取目标内容之前完成，危险链接不会被解引用读取。
119	// ---------------------------------------------------------------------------
120	
121	// 符号链接安全检查失败：携带相对路径与原因（cycle / outside-root）。
122	function symlinkError(fullPath, rootDir, reason) {
123	  const relPath = toPosix(relative(rootDir, fullPath));
124	  const message =
125	    reason === 'cycle'
126	      ? `符号链接形成回路: ${relPath}`
127	      : `符号链接越出产物根目录: ${relPath}`;
128	  return new ProvError(ERROR_CODES.SYMLINK_INVALID, message, { path: relPath, reason });
129	}
130	
131	// 解析真实路径；底层错误按既有归类转换。
132	async function realPathOf(p, context) {
133	  try {
134	    return await realpath(p);
135	  } catch (err) {
136	    throw wrapFsError(err, context);
137	  }
138	}
139	
140	async function walkFiles(rootDir) {
141	  const found = [];
142	  const rootReal = await realPathOf(rootDir, '读取产物目录');
143	  // chain 为当前递归路径上各级目录的真实路径，用于识别指回祖先的链接回路。
144	  async function walk(dir, chain) {
145	    let entries;
146	    try {
147	      entries = await readdir(dir, { withFileTypes: true });
148	    } catch (err) {
149	      throw wrapFsError(err, '读取产物目录');
150	    }
151	    for (const entry of entries) {
152	      const full = join(dir, entry.name);
153	      if (entry.isDirectory()) {
154	        await walk(full, [...chain, await realPathOf(full, '读取产物目录')]);
155	      } else if (entry.isFile()) {
156	        found.push(full);
157	      } else if (entry.isSymbolicLink()) {
158	        // 先解析真实目标并做安全判定，再按目标类型处理：
159	        // 指向目录则继续递归，指向文件则按链接路径记录。
160	        let targetReal;
161	        try {
162	          targetReal = await realpath(full);
163	        } catch (err) {
164	          // 链接互相指向成环（如 a -> b、b -> a）时 realpath 报 ELOOP。
165	          if (err && err.code === 'ELOOP') throw symlinkError(full, rootDir, 'cycle');
166	          throw wrapFsError(err, '读取符号链接');
167	        }
168	        if (!isWithin(targetReal, rootReal)) {
169	          throw symlinkError(full, rootDir, 'outside-root');
170	        }
171	        if (chain.includes(targetReal)) {
172	          throw symlinkError(full, rootDir, 'cycle');
173	        }
174	        let target;
175	        try {
176	          target = await stat(full);
177	        } catch (err) {
178	          throw wrapFsError(err, '读取符号链接');
179	        }
180	        if (target.isDirectory()) await walk(full, [...chain, targetReal]);
181	        else if (target.isFile()) found.push(full);
182	      }
183	      // 其他特殊文件（套接字/设备等）忽略。
184	    }
185	  }
186	  await walk(rootDir, [rootReal]);
187	  return found;
188	}
189	
190	// 判断 root 是否位于 outDir 之内（用于从扫描结果排除输出目录自身）。
191	function isWithin(pathAbs, dirAbs) {
192	  const relPath = relative(dirAbs, pathAbs);
193	  return relPath === '' || (!!relPath && !relPath.startsWith('..') && !isAbsolute(relPath));
194	}
195	
196	async function fileTypeFromPath(fullPath, data) {
197	  // 极简魔数嗅探，仅用于清单的 type 字段；不识别时回退为扩展名或 "data"。
198	  // 一律使用字节数组，避免多字节字符串经 UTF-8 编码后长度/取值不符。
199	  const startsWith = (bytes) =>
200	    data.length >= bytes.length && bytes.every((b, i) => data[i] === b);
201	  if (startsWith([0x1f, 0x8b])) return 'application/gzip';
202	  if (startsWith([0x50, 0x4b, 0x03, 0x04])) return 'application/zip';
203	  if (startsWith([0x25, 0x50, 0x44, 0x46, 0x2d])) return 'application/pdf'; // %PDF-
204	  if (startsWith([0x7f, 0x45, 0x4c, 0x46])) return 'application/x-elf';
205	  if (startsWith([0x4d, 0x5a])) return 'application/x-dosexec'; // MZ
206	  if (startsWith([0xff, 0xd8, 0xff])) return 'image/jpeg';
207	  if (startsWith([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image/png';
208	  // 类脚本/文本：UTF BOM，或前 512 字节不含 NUL 则视为 text。
209	  if (
210	    startsWith([0xef, 0xbb, 0xbf]) ||
211	    startsWith([0xff, 0xfe]) ||
212	    startsWith([0xfe, 0xff])
213	  ) {
214	    return 'text/plain';
215	  }
216	  if (!data.subarray(0, 512).includes(0)) return 'text/plain';
217	  const ext = basename(fullPath).split('.').pop();
218	  return ext && ext !== basename(fullPath) ? `application/x-${ext.toLowerCase()}` : 'application/octet-stream';
219	}
220	
221	// 构建 SBOM。时间字段不进入清单，文件摘要只依赖文件字节与相对路径。
222	// excludeDir 为输出目录的绝对路径（若位于产物内部则排除）。
223	export async function buildSbom(artifactPath, excludeDir) {
224	  const artifactAbs = resolve(artifactPath);
225	  let artifactStat;
226	  try {
227	    artifactStat = await stat(artifactAbs);
228	  } catch (err) {
229	    throw wrapFsError(err, '读取产物');
230	  }
231	
232	  const rootDir = artifactStat.isDirectory() ? artifactAbs : dirname(artifactAbs);
233	  const excludeAbs = excludeDir ? resolve(excludeDir) : null;
234	
235	  let files;
236	  if (artifactStat.isDirectory()) {
237	    files = await walkFiles(artifactAbs);
238	  } else {
239	    files = [artifactAbs];
240	  }
241	
242	  const entries = [];
243	  for (const full of files) {
244	    if (excludeAbs && isWithin(full, excludeAbs)) continue;
245	    let data;
246	    try {
247	      data = await readFile(full);
248	    } catch (err) {
249	      throw wrapFsError(err, '读取产物文件');
250	    }
251	    const relPath = toPosix(relative(rootDir, full));
252	    entries.push({
253	      path: relPath,
254	      sha256: sha256Hex(data),
255	      size: data.length,
256	      type: await fileTypeFromPath(full, data),
257	    });
258	  }
259	
260	  // 按相对路径排序，保证同一输入产生字节级一致的清单。
261	  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
262	
263	  return {
264	    schemaVersion: '1.0',
265	    artifactName: artifactStat.isDirectory() ? basename(artifactAbs) : basename(artifactAbs),
266	    rootType: artifactStat.isDirectory() ? 'directory' : 'file',
267	    files: entries,
268	  };
269	}
270	
271	// 顶层产物摘要：对“排序后的文件条目列表”做稳定哈希。
272	// 任何字节变化、文件新增/删除/重命名都会改变该摘要。
273	export function computeArtifactDigest(sbom) {
274	  return sha256Hex(stableJsonStringify(sbom.files));
275	}
276	
277	// ---------------------------------------------------------------------------
278	// 密钥与签名（Ed25519，PEM）
279	// ---------------------------------------------------------------------------
280	
281	function readPrivateKey(keyPath) {
282	  let pem;
283	  try {
284	    pem = readFileSync(keyPath);
285	  } catch (err) {
286	    throw wrapFsError(err, '读取私钥');
287	  }
288	  let keyObj;
289	  try {
290	    keyObj = createPrivateKey({ key: pem, format: 'pem' });
291	  } catch {
292	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `私钥无法解析或格式不受支持: ${keyPath}`);
293	  }
294	  if (keyObj.asymmetricKeyType !== 'ed25519') {
295	    throw new ProvError(
296	      ERROR_CODES.KEY_NOT_FOUND,
297	      `私钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
298	    );
299	  }
300	  return keyObj;
301	}
302	
303	function readPublicKey(keyPath) {
304	  let pem;
305	  try {
306	    pem = readFileSync(keyPath);
307	  } catch (err) {
308	    throw wrapFsError(err, '读取公钥');
309	  }
310	  let keyObj;
311	  try {
312	    keyObj = createPublicKey({ key: pem, format: 'pem' });
313	  } catch {
314	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `公钥无法解析或格式不受支持: ${keyPath}`);
315	  }
316	  if (keyObj.asymmetricKeyType !== 'ed25519') {
317	    throw new ProvError(
318	      ERROR_CODES.KEY_NOT_FOUND,
319	      `公钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
320	    );
321	  }
322	  return keyObj;
323	}
324	
325	// 生成阶段时间戳采用 UTC ISO-8601；它只写入 proof，不参与任何摘要。
326	function nowIso() {
327	  return new Date().toISOString();
328	}
329	
330	// ---------------------------------------------------------------------------
331	// keygen
332	// ---------------------------------------------------------------------------
333	
334	export async function keygen({ keyDir, name = 'provguard' }) {
335	  const absDir = resolve(keyDir);
336	  try {
337	    await mkdir(absDir, { recursive: true });
338	  } catch (err) {
339	    throw wrapFsError(err, '创建密钥目录');
340	  }
341	  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
342	  const privPath = join(absDir, `${name}.private.pem`);
343	  const pubPath = join(absDir, `${name}.public.pem`);
344	  try {
345	    await writeFile(
346	      privPath,
347	      privateKey.export({ type: 'pkcs8', format: 'pem' }),
348	      { mode: 0o600 },
349	    );
350	    await writeFile(
351	      pubPath,
352	      publicKey.export({ type: 'spki', format: 'pem' }),
353	      { mode: 0o644 },
354	    );
355	  } catch (err) {
356	    throw wrapFsError(err, '写入密钥');
357	  }
358	  return { privateKeyPath: privPath, publicKeyPath: pubPath };
359	}
360	
361	// ---------------------------------------------------------------------------
362	// generate
363	// ---------------------------------------------------------------------------
364	
365	export async function generate({ artifact, key, out, coKeys = [], bundle = false }) {
366	  // 输入检查：产物与私钥必须存在且可读。
367	  const artifactAbs = resolve(artifact);
368	  const keyAbs = resolve(key);
369	  const coSign = coKeys.length > 0;
370	  const coKeyAbsList = coKeys.map((p) => resolve(p));
371	  const inputs = [
372	    [artifactAbs, '产物'],
373	    [keyAbs, '私钥'],
374	  ];
375	  for (const p of coKeyAbsList) inputs.push([p, '共签私钥']);
376	  for (const [p, label] of inputs) {
377	    try {
378	      await access(p, fsConstants.R_OK);
379	    } catch (err) {
380	      throw wrapFsError(err, `读取${label}`);
381	    }
382	  }
383	
384	  const outAbs = resolve(out);
385	  const parent = dirname(outAbs);
386	  try {
387	    await mkdir(parent, { recursive: true });
388	  } catch (err) {
389	    throw wrapFsError(err, '创建输出目录');
390	  }
391	
392	  // 若输出目录尚不存在，先按真实路径创建，再据此排除。
393	  try {
394	    await mkdir(outAbs, { recursive: true });
395	  } catch (err) {
396	    throw wrapFsError(err, '创建输出目录');
397	  }
398	  let outReal;
399	  try {
400	    outReal = await realpath(outAbs);
401	  } catch (err) {
402	    throw wrapFsError(err, '解析输出目录');
403	  }
404	
405	  const privateKey = readPrivateKey(keyAbs);
406	  // 由私钥导出对应公钥，记录其指纹到证明中，供验证区分错误公钥与签名失配。
407	  const signingPublicKey = createPublicKey(privateKey);
408	  const signerKeyFingerprint = keyFingerprint(signingPublicKey);
409	
410	  // 共签私钥：逐一读取并校验为 Ed25519；指纹不得重复，也不得与主签名密钥相同，
411	  // 否则为 USAGE_ERROR。共签者按指纹升序排列，保证输出确定。
412	  const coSigners = [];
413	  if (coSign) {
414	    const seen = new Set([signerKeyFingerprint.toLowerCase()]);
415	    for (const p of coKeyAbsList) {
416	      const coKey = readPrivateKey(p);
417	      const fingerprint = keyFingerprint(createPublicKey(coKey));
418	      if (seen.has(fingerprint.toLowerCase())) {
419	        throw new ProvError(
420	          ERROR_CODES.USAGE_ERROR,
421	          '共签私钥重复或与主密钥相同（--co-key 必须互不相同且不同于 --key）',
422	        );
423	      }
424	      seen.add(fingerprint.toLowerCase());
425	      coSigners.push({ key: coKey, fingerprint });
426	    }
427	    coSigners.sort((a, b) => (a.fingerprint < b.fingerprint ? -1 : a.fingerprint > b.fingerprint ? 1 : 0));
428	  }
429	
430	  const sbom = await buildSbom(artifactAbs, outReal);
431	  const artifactDigest = computeArtifactDigest(sbom);
432	
433	  // SBOM 规范字节：稳定 JSON（去尾换行后的 UTF-8）。proof 中的 sbomDigest 与
434	  // sbom.json.sig 绑定同一组字节，防止证明有效而 sbom.json 被整体替换。
435	  const sbomCanonical = stableJsonStringify(sbom);
436	  const sbomDigest = sha256Hex(sbomCanonical);
437	
438	  const proof = {
439	    proofVersion: coSign ? PROOF_VERSION_COSIGN : PROOF_VERSION,
440	    artifactName: basename(artifactAbs),
441	    artifactDigest,
442	    fileName: basename(artifactAbs),
443	    size: sbom.files.reduce((n, f) => n + f.size, 0),
444	    generatedAt: nowIso(),
445	    signerKeyFingerprint,
446	    sbomDigest,
447	    files: sbom.files,
448	  };
449	  // 启用共签时证明声明共签者集合（按指纹升序、已去重），随证明一起被主签名保护。
450	  if (coSign) {
451	    proof.cosignerKeyFingerprints = coSigners.map((c) => c.fingerprint);
452	  }
453	  // 稳定字段顺序：proof 先按既定顺序构造，再整体排序输出。
454	  const proofJson = stableJsonStringify(proof) + '\n';
455	  const sbomJson = sbomCanonical + '\n';
456	
457	  // 对证明的规范字节（不含尾部换行）签名，验证时使用同一规范形式。
458	  // Ed25519 为纯签名算法，不接受摘要算法参数，故用 sign(null, data, key)。
459	  const signature = cryptoSign(null, Buffer.from(proofJson.trimEnd(), 'utf8'), privateKey);
460	  const signatureB64 = signature.toString('base64') + '\n';
461	  // 对 SBOM 规范字节单独签名，Base64 加换行保存。
462	  const sbomSignature = cryptoSign(null, Buffer.from(sbomCanonical, 'utf8'), privateKey);
463	  const sbomSignatureB64 = sbomSignature.toString('base64') + '\n';
464	
465	  const proofPath = join(outReal, 'proof.json');
466	  const sbomPath = join(outReal, 'sbom.json');
467	  const sigPath = join(outReal, 'proof.json.sig');
468	  const sbomSigPath = join(outReal, 'sbom.json.sig');
469	  // 共签清单：每个共签者对与主签名相同的证明规范字节签名（proof.cosignatures.json），
470	  // 并另对 SBOM 规范字节签名（sbom.cosignatures.json）。不提供 --co-key 时不创建这些文件。
471	  const proofCosigPath = coSign ? join(outReal, 'proof.cosignatures.json') : null;
472	  const sbomCosigPath = coSign ? join(outReal, 'sbom.cosignatures.json') : null;
473	  // 证明分发包：--bundle 时在输出目录额外写出 proof.bundle.json（不影响既有文件）。
474	  const bundlePath = bundle ? join(outReal, 'proof.bundle.json') : null;
475	  try {
476	    await atomicWrite(proofPath, proofJson);
477	    await atomicWrite(sbomPath, sbomJson);
478	    await atomicWrite(sigPath, signatureB64);
479	    await atomicWrite(sbomSigPath, sbomSignatureB64);
480	    let proofCosigJson = null;
481	    let sbomCosigJson = null;
482	    if (coSign) {
483	      const proofBytes = Buffer.from(proofJson.trimEnd(), 'utf8');
484	      const sbomBytes = Buffer.from(sbomCanonical, 'utf8');
485	      const cosignManifest = (bytes) => ({
486	        schemaVersion: COSIGN_SCHEMA_VERSION,
487	        artifactDigest,
488	        sbomDigest,
489	        signers: coSigners.map((c) => ({
490	          keyFingerprint: c.fingerprint,
491	          signature: cryptoSign(null, bytes, c.key).toString('base64'),
492	        })),
493	      });
494	      proofCosigJson = stableJsonStringify(cosignManifest(proofBytes)) + '\n';
495	      sbomCosigJson = stableJsonStringify(cosignManifest(sbomBytes)) + '\n';
496	      await atomicWrite(proofCosigPath, proofCosigJson);
497	      await atomicWrite(sbomCosigPath, sbomCosigJson);
498	    }
499	    if (bundle) {
500	      const entries = [
501	        ['proof', proofJson],
502	        ['proof-signature', signatureB64],
503	        ['sbom', sbomJson],
504	        ['sbom-signature', sbomSignatureB64],
505	      ];
506	      if (coSign) {
507	        entries.push(['proof-cosignatures', proofCosigJson], ['sbom-cosignatures', sbomCosigJson]);
508	      }
509	      await atomicWrite(bundlePath, buildBundleJson(entries));
510	    }
511	  } catch (err) {
512	    throw wrapFsError(err, '写入证明产物');
513	  }
514	
515	  const result = {
516	    proofPath,
517	    sbomPath,
518	    signaturePath: sigPath,
519	    sbomSignaturePath: sbomSigPath,
520	    artifactDigest,
521	    sbomDigest,
522	    fileCount: sbom.files.length,
523	    proofVersion: proof.proofVersion,
524	  };
525	  if (coSign) {
526	    result.cosignerCount = coSigners.length;
527	    result.proofCosignaturesPath = proofCosigPath;
528	    result.sbomCosignaturesPath = sbomCosigPath;
529	  }
530	  if (bundle) {
531	    result.bundlePath = bundlePath;
532	  }
533	  return result;
534	}
