536	// ---------------------------------------------------------------------------
537	// 证明分发包（proof.bundle.json）：把一套证明产物打包为单个稳定 JSON 文件。
538	// members 按逻辑名排序（stableJsonStringify 按键名排序），每项保存原文件字节的
539	// Base64、SHA-256 与字节长度；原样保留文件字节（含签名输入的规范字节），
540	// 因此除 generatedAt、proof 及其签名外，重复生成的包内容逐字节稳定。
541	// ---------------------------------------------------------------------------
542	
543	function bundleMember(content) {
544	  const buf = Buffer.isBuffer(content) ? content : Buffer.from(content, 'utf8');
545	  return { data: buf.toString('base64'), sha256: sha256Hex(buf), size: buf.length };
546	}
547	
548	function buildBundleJson(entries) {
549	  const members = {};
550	  for (const [name, content] of entries) members[name] = bundleMember(content);
551	  return stableJsonStringify({ bundleVersion: BUNDLE_VERSION, members }) + '\n';
552	}
553	
554	// 解析并校验分发包结构，返回 { members: Map<逻辑名, Buffer>, hasCosignMembers }。
555	// JSON 不可解析、bundleVersion 非 1.0、成员缺失或多余、Base64 非法、
556	// 长度或 SHA-256 不符均为 PROOF_INVALID。
557	function parseBundle(text) {
558	  let bundle;
559	  try {
560	    bundle = JSON.parse(text);
561	  } catch {
562	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明分发包不是合法的 JSON');
563	  }
564	  if (bundle === null || typeof bundle !== 'object' || Array.isArray(bundle)) {
565	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明分发包顶层必须是 JSON 对象');
566	  }
567	  if (bundle.bundleVersion !== BUNDLE_VERSION) {
568	    throw new ProvError(
569	      ERROR_CODES.PROOF_INVALID,
570	      `分发包 bundleVersion 缺失或不受支持（应为 ${BUNDLE_VERSION}）`,
571	    );
572	  }
573	  const rawMembers = bundle.members;
574	  if (rawMembers === null || typeof rawMembers !== 'object' || Array.isArray(rawMembers)) {
575	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '分发包字段缺失或类型非法: members');
576	  }
577	  const known = new Set([...BUNDLE_BASE_MEMBERS, ...BUNDLE_COSIGN_MEMBERS]);
578	  for (const name of Object.keys(rawMembers)) {
579	    if (!known.has(name)) {
580	      throw new ProvError(ERROR_CODES.PROOF_INVALID, `分发包含有多余成员: ${name}`);
581	    }
582	  }
583	  for (const name of BUNDLE_BASE_MEMBERS) {
584	    if (!(name in rawMembers)) {
585	      throw new ProvError(ERROR_CODES.PROOF_INVALID, `分发包缺少成员: ${name}`);
586	    }
587	  }
588	  // 共签成员必须成对出现（与生成时的输出一致）。
589	  const hasProofCosig = BUNDLE_COSIGN_MEMBERS[0] in rawMembers;
590	  const hasSbomCosig = BUNDLE_COSIGN_MEMBERS[1] in rawMembers;
591	  if (hasProofCosig !== hasSbomCosig) {
592	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '分发包共签成员必须成对出现');
593	  }
594	  const members = new Map();
595	  for (const [name, m] of Object.entries(rawMembers)) {
596	    members.set(name, decodeBundleMember(name, m));
597	  }
598	  return { members, hasCosignMembers: hasProofCosig };
599	}
600	
601	function decodeBundleMember(name, member) {
602	  const bad = (why) => new ProvError(ERROR_CODES.PROOF_INVALID, `分发包成员 ${name} ${why}`);
603	  if (member === null || typeof member !== 'object' || Array.isArray(member)) {
604	    throw bad('必须是对象');
605	  }
606	  if (typeof member.data !== 'string' || !/^[A-Za-z0-9+/]*={0,2}$/.test(member.data)) {
607	    throw bad('的 data 不是合法的 Base64 内容');
608	  }
609	  if (typeof member.sha256 !== 'string' || !/^[0-9a-f]{64}$/i.test(member.sha256)) {
610	    throw bad('的 sha256 不是合法的 SHA-256 十六进制摘要');
611	  }
612	  if (!isNonNegSafeInt(member.size)) {
613	    throw bad('的 size 非法（应为非负安全整数）');
614	  }
615	  const buf = Buffer.from(member.data, 'base64');
616	  if (buf.length !== member.size) {
617	    throw bad('的字节长度与 size 不符');
618	  }
619	  if (sha256Hex(buf).toLowerCase() !== member.sha256.toLowerCase()) {
620	    throw bad('的 SHA-256 与内容不符');
621	  }
622	  return buf;
623	}
624	
625	// 同目录临时文件 + rename，避免半成品证明文件留在输出目录。
626	async function atomicWrite(target, contents) {
627	  const dir = dirname(target);
628	  const tmp = join(dir, `.${basename(target)}.${process.pid}.tmp`);
629	  await writeFile(tmp, contents, { mode: 0o644 });
630	  try {
631	    await rename(tmp, target);
632	  } catch (err) {
633	    await rm(tmp, { force: true });
634	    throw err;
635	  }
636	}
