638	// ---------------------------------------------------------------------------
639	// verify
640	// ---------------------------------------------------------------------------
641	
642	export async function verify({
643	  artifact,
644	  proof: proofPath,
645	  signature: sigPath,
646	  key: pubKeyPath,
647	  sbom: sbomPath,
648	  sbomSignature: sbomSigPath,
649	  policy: policyPath,
650	  cosignatures: cosigDir,
651	  cosignerKeys,
652	  minCosigners,
653	  bundle: bundlePath,
654	}) {
655	  const bundleMode = bundlePath !== undefined;
656	  const artifactAbs = resolve(artifact);
657	  const keyAbs = resolve(pubKeyPath);
658	  const bundleAbs = bundleMode ? resolve(bundlePath) : null;
659	  const proofAbs = bundleMode ? null : resolve(proofPath);
660	  const sigAbs = bundleMode ? null : resolve(sigPath);
661	
662	  // --sbom 与 --sbom-signature 必须成对出现；只给一者是用法错误。
663	  // 包模式自带 SBOM 与其签名成员，视为始终启用 SBOM 校验。
664	  let sbomMode = true;
665	  let sbomAbs = null;
666	  let sbomSigAbs = null;
667	  if (!bundleMode) {
668	    sbomMode = sbomPath !== undefined || sbomSigPath !== undefined;
669	    if (sbomMode && (sbomPath === undefined || sbomSigPath === undefined)) {
670	      throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
671	    }
672	    sbomAbs = sbomMode ? resolve(sbomPath) : null;
673	    sbomSigAbs = sbomMode ? resolve(sbomSigPath) : null;
674	  }
675	
676	  // 共签校验参数必须成套：独立文件模式为 --cosignatures、--cosigner-key（可重复）、
677	  // --min-cosigners 三者；包模式清单位于包内，只需后两者。
678	  const cosignMode =
679	    cosigDir !== undefined || cosignerKeys !== undefined || minCosigners !== undefined;
680	  if (cosignMode) {
681	    const pairOk = cosignerKeys !== undefined && minCosigners !== undefined;
682	    const sourceOk = bundleMode || cosigDir !== undefined;
683	    if (!pairOk || !sourceOk) {
684	      throw new ProvError(
685	        ERROR_CODES.USAGE_ERROR,
686	        bundleMode
687	          ? '--cosigner-key 与 --min-cosigners 必须同时提供'
688	          : '--cosignatures、--cosigner-key 与 --min-cosigners 必须同时提供',
689	      );
690	    }
691	  }
692	  const cosignerKeyList = cosignMode
693	    ? (Array.isArray(cosignerKeys) ? cosignerKeys : [cosignerKeys])
694	    : [];
695	
696	  // 1) 所有输入必须存在且可读。
697	  const inputs = [[artifactAbs, '产物']];
698	  if (bundleMode) {
699	    inputs.push([bundleAbs, '证明分发包']);
700	  } else {
701	    inputs.push([proofAbs, '证明文件'], [sigAbs, '签名文件']);
702	  }
703	  inputs.push([keyAbs, '公钥']);
704	  if (!bundleMode && sbomMode) {
705	    inputs.push([sbomAbs, 'SBOM 文件'], [sbomSigAbs, 'SBOM 签名文件']);
706	  }
707	  for (const [p, label] of inputs) {
708	    try {
709	      await access(p, fsConstants.R_OK);
710	    } catch (err) {
711	      throw wrapFsError(err, `读取${label}`);
712	    }
713	  }
714	
715	  // 2) 公钥必须可解析且为 Ed25519 —— 错误/不支持的公钥归 KEY_NOT_FOUND。
716	  const publicKey = readPublicKey(keyAbs);
717	
718	  // 3) 证明来源：包模式先解析并校验分发包结构，再取出各成员原始字节；
719	  //    独立文件模式直接读取对应文件。
720	  let bundleMembers = null;
721	  let hasCosignMembers = false;
722	  let proofText;
723	  let sigText;
724	  let sbomText = null;
725	  let sbomSigText = null;
726	  if (bundleMode) {
727	    const bundleText = await readFileUtf8(bundleAbs);
728	    const parsed = parseBundle(bundleText);
729	    bundleMembers = parsed.members;
730	    hasCosignMembers = parsed.hasCosignMembers;
731	    proofText = bundleMembers.get('proof').toString('utf8');
732	    sigText = bundleMembers.get('proof-signature').toString('utf8');
733	    sbomText = bundleMembers.get('sbom').toString('utf8');
734	    sbomSigText = bundleMembers.get('sbom-signature').toString('utf8');
735	  } else {
736	    try {
737	      proofText = await readFileUtf8(proofAbs);
738	    } catch (err) {
739	      throw wrapFsError(err, '读取证明文件');
740	    }
741	  }
742	  // 证明文件必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
743	  let proof;
744	  try {
745	    proof = JSON.parse(proofText);
746	  } catch {
747	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明文件不是合法的 JSON');
748	  }
749	  const proofError = validateProof(proof);
750	  if (proofError) {
751	    throw new ProvError(ERROR_CODES.PROOF_INVALID, proofError);
752	  }
753	
754	  // 包模式：共签成员与证明声明必须一致 —— 声明了共签者而缺少共签成员，
755	  // 或未声明却携带共签成员，均为成员缺失/多余（PROOF_INVALID）。
756	  if (bundleMode) {
757	    const declared = proof.cosignerKeyFingerprints !== undefined;
758	    if (declared && !hasCosignMembers) {
759	      throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明声明了共签者，但分发包缺少共签成员');
760	    }
761	    if (!declared && hasCosignMembers) {
762	      throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明未声明共签者，但分发包含有共签成员');
763	    }
764	  }
765	
766	  // 4) 签名必须是合法 Base64 且长度符合 Ed25519（64 字节）—— 否则 PROOF_INVALID。
767	  if (!bundleMode) {
768	    sigText = await readFileUtf8(sigAbs);
769	  }
770	  const sigB64 = sigText.replace(/\s+/g, '');
771	  let sigBuf;
772	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
773	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件不是合法的 Base64 内容');
774	  }
775	  try {
776	    sigBuf = Buffer.from(sigB64, 'base64');
777	  } catch {
778	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件无法解码为字节');
779	  }
780	  if (sigBuf.length !== 64) {
781	    throw new ProvError(
782	      ERROR_CODES.PROOF_INVALID,
783	      `签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
784	    );
785	  }
786	
787	  // 5) 重算证明的规范字节并验签。
788	  //    以磁盘上的 proof.json 原样为真，重新序列化其解析结果用于验签；
789	  //    generate 写出的即为稳定规范形式，因此往返一致。
790	  //
791	  //    错误归类（三者互不相同）：
792	  //      - 提供的公钥与证明中记录的签钥指纹不一致  -> KEY_NOT_FOUND（错误公钥）
793	  //      - 公钥一致但签名验证失败                  -> SIGNATURE_INVALID（签名内容不匹配）
794	  //      - 签名文件本身格式非法（前面）            -> PROOF_INVALID
795	  const providedFingerprint = keyFingerprint(publicKey);
796	  if (providedFingerprint.toLowerCase() !== proof.signerKeyFingerprint.toLowerCase()) {
797	    throw new ProvError(
798	      ERROR_CODES.KEY_NOT_FOUND,
799	      '提供的公钥与证明记录的签名密钥不一致（可能使用了错误公钥）',
800	      {
801	        providedKeyFingerprint: providedFingerprint,
802	        proofKeyFingerprint: proof.signerKeyFingerprint,
803	      },
804	    );
805	  }
806	
807	  const canonicalProof = stableJsonStringify(proof);
808	  let sigOk = false;
809	  try {
810	    sigOk = cryptoVerify(null, Buffer.from(canonicalProof, 'utf8'), publicKey, sigBuf);
811	  } catch {
812	    sigOk = false;
813	  }
814	  if (!sigOk) {
815	    throw new ProvError(
816	      ERROR_CODES.SIGNATURE_INVALID,
817	      '签名与证明内容不匹配（证明可能被改动，或签名已损坏）',
818	    );
819	  }
820	
821	  // 6) 签名通过后重新扫描产物并逐项比对 —— 任何差异均为 INTEGRITY_MISMATCH。
822	  //    排除输出目录：证明/签名/清单（或分发包）通常与产物相邻，验证时不得把它们计入产物。
823	  const excludeDir = inferExcludeDir(bundleMode ? bundleAbs : proofAbs, artifactAbs);
824	  const currentSbom = await buildSbom(artifactAbs, excludeDir);
825	  const currentDigest = computeArtifactDigest(currentSbom);
826	
827	  const mismatches = diffManifest(proof, currentSbom, currentDigest);
828	  if (mismatches.length > 0) {
829	    throw new ProvError(
830	      ERROR_CODES.INTEGRITY_MISMATCH,
831	      `检测到 ${mismatches.length} 处完整性差异`,
832	      { mismatches },
833	    );
834	  }
835	
836	  // 7) SBOM 校验：结构、proof.sbomDigest、SBOM 签名，
837	  //    并确认 SBOM 清单与证明清单（进而与当前扫描）逐项一致。
838	  //    包模式始终执行（成员来自分发包）；独立文件模式仅在成对提供时执行。
839	  let sbomDigest;
840	  if (sbomMode) {
841	    if (!bundleMode) {
842	      sbomText = await readFileUtf8(sbomAbs);
843	      sbomSigText = await readFileUtf8(sbomSigAbs);
844	    }
845	    sbomDigest = await verifySbom({ sbomText, sbomSigText, proof, publicKey });
846	  }
847	
848	  // 8) 共签模式：在证明、可选 SBOM 与产物完整性全部通过后，校验共签清单与各共签签名。
849	  let cosignerCount;
850	  if (cosignMode) {
851	    let proofManifestText;
852	    let sbomManifestText;
853	    if (bundleMode) {
854	      if (!hasCosignMembers) {
855	        throw new ProvError(
856	          ERROR_CODES.PROOF_INVALID,
857	          '分发包缺少共签成员（proof-cosignatures / sbom-cosignatures）',
858	        );
859	      }
860	      proofManifestText = bundleMembers.get('proof-cosignatures').toString('utf8');
861	      sbomManifestText = bundleMembers.get('sbom-cosignatures').toString('utf8');
862	    }
863	    cosignerCount = await verifyCosignatures({
864	      cosigDir,
865	      proofManifestText,
866	      sbomManifestText,
867	      cosignerKeyPaths: cosignerKeyList,
868	      minCosigners,
869	      proof,
870	      canonicalProof,
871	      currentSbom,
872	    });
873	  }
874	
875	  // 9) 可选策略：仅在签名、完整性、可选 SBOM、可选共签校验全部通过后加载并执行。
876	  //    策略文件自身缺失/不可读/非法按其错误码返回（INPUT_NOT_FOUND /
877	  //    PERMISSION_DENIED / POLICY_INVALID）；内容违规为 POLICY_VIOLATION。
878	  let policyStatus;
879	  if (policyPath !== undefined) {
880	    const policy = await loadPolicy(policyPath);
881	    const violations = evaluatePolicy(policy, proof, sbomMode);
882	    if (violations.length > 0) {
883	      throw new ProvError(
884	        ERROR_CODES.POLICY_VIOLATION,
885	        `策略校验未通过（${violations.length} 项违规）`,
886	        { violations },
887	      );
888	    }
889	    policyStatus = 'PASS';
890	  }
891	
892	  const result = {
893	    status: 'VERIFIED',
894	    proofVersion: proof.proofVersion,
895	    artifactDigest: currentDigest,
896	    fileCount: currentSbom.files.length,
897	  };
898	  if (sbomMode) result.sbomDigest = sbomDigest;
899	  if (cosignMode) result.cosignerCount = cosignerCount;
900	  if (policyPath !== undefined) result.policyStatus = policyStatus;
901	  return result;
902	}
903	
904	// SBOM 校验：结构 -> 摘要 -> 签名 -> 清单一致性。
905	// sbomText / sbomSigText 为 SBOM 与其签名文件的原始文本（独立文件或分发包成员）。
906	async function verifySbom({ sbomText, sbomSigText, proof, publicKey }) {
907	  // a) sbom.json 必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
908	  let sbom;
909	  try {
910	    sbom = JSON.parse(sbomText);
911	  } catch {
912	    throw new ProvError(ERROR_CODES.PROOF_INVALID, 'SBOM 文件不是合法的 JSON');
913	  }
914	  const sbomError = validateSbom(sbom);
915	  if (sbomError) {
916	    throw new ProvError(ERROR_CODES.PROOF_INVALID, sbomError);
917	  }
918	
919	  // b) 证明必须携带合法的 sbomDigest 字段。
920	  if (typeof proof.sbomDigest !== 'string' || !/^[0-9a-f]{64}$/i.test(proof.sbomDigest)) {
921	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明缺少合法的 sbomDigest 字段');
922	  }
923	
924	  // c) 重算 SBOM 规范字节摘要并与证明比对 —— 不一致说明 sbom.json 被替换或改动。
925	  const canonicalSbom = stableJsonStringify(sbom);
926	  const recomputed = sha256Hex(canonicalSbom);
927	  if (recomputed.toLowerCase() !== proof.sbomDigest.toLowerCase()) {
928	    throw new ProvError(
929	      ERROR_CODES.INTEGRITY_MISMATCH,
930	      'sbom.json 与证明记录的 sbomDigest 不一致（SBOM 可能被替换）',
931	      { mismatches: [{ path: 'sbom.json', kind: 'content-modified' }] },
932	    );
