1352	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
1353	}
1354	
1355	// 读取并严格校验策略文件。
1356	// 缺失 -> INPUT_NOT_FOUND；不可读 -> PERMISSION_DENIED；
1357	// JSON 不可解析/非对象/未知字段/非法类型或取值/时间区间倒置 -> POLICY_INVALID。
1358	async function loadPolicy(policyPath) {
1359	  const policyAbs = resolve(policyPath);
1360	  let text;
1361	  try {
1362	    text = await readFileUtf8(policyAbs);
1363	  } catch (err) {
1364	    throw wrapFsError(err, '读取策略文件');
1365	  }
1366	  let policy;
1367	  try {
1368	    policy = JSON.parse(text);
1369	  } catch {
1370	    throw new ProvError(ERROR_CODES.POLICY_INVALID, '策略文件不是合法的 JSON');
1371	  }
1372	  if (policy === null || typeof policy !== 'object' || Array.isArray(policy)) {
1373	    throw new ProvError(ERROR_CODES.POLICY_INVALID, '策略顶层必须是 JSON 对象');
1374	  }
1375	
1376	  const allowed = new Set([
1377	    'policyVersion',
1378	    'proofNotBefore',
1379	    'proofNotAfter',
1380	    'allowedKeyFingerprints',
1381	    'requireSbom',
1382	    'maxFileCount',
1383	    'maxSize',
1384	  ]);
1385	  for (const key of Object.keys(policy)) {
1386	    if (!allowed.has(key)) {
1387	      throw new ProvError(ERROR_CODES.POLICY_INVALID, `策略包含未知字段: ${key}`);
1388	    }
1389	  }
1390	
1391	  // policyVersion 必填，字符串且固定为 "1.0"。
1392	  if (policy.policyVersion === undefined) {
1393	    throw new ProvError(ERROR_CODES.POLICY_INVALID, '策略缺少必填字段: policyVersion');
1394	  }
1395	  if (typeof policy.policyVersion !== 'string') {
1396	    throw new ProvError(ERROR_CODES.POLICY_INVALID, '策略字段类型非法: policyVersion');
1397	  }
1398	  if (policy.policyVersion !== POLICY_VERSION) {
1399	    throw new ProvError(
1400	      ERROR_CODES.POLICY_INVALID,
1401	      `不支持的策略版本: ${policy.policyVersion}`,
1402	    );
1403	  }
1404	
1405	  // 时间字段可选；出现时必须是合法 UTC ISO-8601 字符串。
1406	  for (const k of ['proofNotBefore', 'proofNotAfter']) {
1407	    if (policy[k] !== undefined && parseUtcIso(policy[k]) === null) {
1408	      throw new ProvError(ERROR_CODES.POLICY_INVALID, `策略字段取值非法: ${k}`);
1409	    }
1410	  }
1411	
1412	  // 指纹白名单可选；缺省不约束，显式给出时必须为非空 SHA-256 十六进制数组。
1413	  if (policy.allowedKeyFingerprints !== undefined) {
1414	    if (!Array.isArray(policy.allowedKeyFingerprints)) {
1415	      throw new ProvError(ERROR_CODES.POLICY_INVALID, '策略字段类型非法: allowedKeyFingerprints');
1416	    }
1417	    if (policy.allowedKeyFingerprints.length === 0) {
1418	      throw new ProvError(
1419	        ERROR_CODES.POLICY_INVALID,
1420	        '策略字段 allowedKeyFingerprints 不允许为空数组',
1421	      );
1422	    }
1423	    for (const fp of policy.allowedKeyFingerprints) {
1424	      if (typeof fp !== 'string' || !/^[0-9a-f]{64}$/i.test(fp)) {
1425	        throw new ProvError(
1426	          ERROR_CODES.POLICY_INVALID,
1427	          '策略字段 allowedKeyFingerprints 中存在非法的 SHA-256 十六进制指纹',
1428	        );
1429	      }
1430	    }
1431	  }
1432	
1433	  if (policy.requireSbom !== undefined && typeof policy.requireSbom !== 'boolean') {
1434	    throw new ProvError(ERROR_CODES.POLICY_INVALID, '策略字段类型非法: requireSbom');
1435	  }
1436	  for (const k of ['maxFileCount', 'maxSize']) {
1437	    if (policy[k] !== undefined && !isNonNegSafeInt(policy[k])) {
1438	      throw new ProvError(ERROR_CODES.POLICY_INVALID, `策略字段取值非法: ${k}`);
1439	    }
1440	  }
1441	
1442	  // 时间区间不得倒置；相等（闭区间单点）允许。
1443	  if (policy.proofNotBefore !== undefined && policy.proofNotAfter !== undefined) {
1444	    if (parseUtcIso(policy.proofNotBefore) > parseUtcIso(policy.proofNotAfter)) {
1445	      throw new ProvError(
1446	        ERROR_CODES.POLICY_INVALID,
1447	        '策略时间区间非法：proofNotBefore 晚于 proofNotAfter',
1448	      );
1449	    }
1450	  }
1451	
1452	  return policy;
1453	}
1454	
1455	// 在签名、完整性、可选 SBOM 校验全部通过后执行策略。
1456	// 返回违规列表（已按时间、密钥、SBOM、文件数、大小排序）；空列表表示通过。
1457	// 每条违规形如 { rule, observed }。
1458	function evaluatePolicy(policy, proof, sbomMode) {
1459	  const violations = [];
1460	  const push = (rule, observed) => violations.push({ rule, observed });
1461	
1462	  // 1) 时间窗口：proof.generatedAt 必须落在闭区间；字段非法单独记。
1463	  const generatedAtMs = parseUtcIso(proof.generatedAt);
1464	  if (generatedAtMs === null) {
1465	    push('generated-at-invalid', proof.generatedAt);
1466	  } else {
1467	    if (policy.proofNotBefore !== undefined && generatedAtMs < parseUtcIso(policy.proofNotBefore)) {
1468	      push('proof-not-before', proof.generatedAt);
1469	    }
1470	    if (policy.proofNotAfter !== undefined && generatedAtMs > parseUtcIso(policy.proofNotAfter)) {
1471	      push('proof-not-after', proof.generatedAt);
1472	    }
1473	  }
1474	
1475	  // 2) 密钥指纹必须命中白名单（大小写不敏感）。
1476	  if (policy.allowedKeyFingerprints !== undefined) {
1477	    const trusted = policy.allowedKeyFingerprints.map((fp) => fp.toLowerCase());
1478	    if (!trusted.includes(proof.signerKeyFingerprint.toLowerCase())) {
1479	      push('allowed-key-fingerprints', proof.signerKeyFingerprint);
1480	    }
1481	  }
1482	
1483	  // 3) requireSbom：必须成对提供 --sbom/--sbom-signature；其有效性已在前面校验。
1484	  //    requireSbom 为 false 时不禁用额外提供的 SBOM（沿用既有校验）。
1485	  if (policy.requireSbom === true && !sbomMode) {
1486	    push('require-sbom', 'absent');
1487	  }
1488	
1489	  // 4) 文件数上限。
1490	  if (policy.maxFileCount !== undefined && proof.files.length > policy.maxFileCount) {
1491	    push('max-file-count', proof.files.length);
1492	  }
1493	
1494	  // 5) 总大小上限。
1495	  if (policy.maxSize !== undefined && proof.size > policy.maxSize) {
1496	    push('max-size', proof.size);
1497	  }
1498	
1499	  return violations;
1500	}
1501	
1502	// ---------------------------------------------------------------------------
1503	// CLI
1504	// ---------------------------------------------------------------------------
1505	
1506	function parseArgs(argv) {
1507	  const args = { _: [] };
1508	  // 可重复参数：每次出现都追加到数组；其余参数保持“后出现覆盖先出现”。
1509	  const repeatable = new Set(['co-key', 'cosigner-key']);
1510	  for (let i = 0; i < argv.length; i += 1) {
1511	    const a = argv[i];
1512	    if (a.startsWith('--')) {
1513	      const key = a.slice(2);
1514	      const next = argv[i + 1];
1515	      const hasValue = next !== undefined && !next.startsWith('--');
1516	      const value = hasValue ? next : true;
1517	      if (hasValue) i += 1;
1518	      if (repeatable.has(key)) {
1519	        if (args[key] === undefined) args[key] = [];
1520	        args[key].push(value);
1521	      } else {
1522	        args[key] = value;
1523	      }
1524	    } else {
1525	      args._.push(a);
1526	    }
1527	  }
1528	  return args;
1529	}
1530	
1531	function usage() {
1532	  return [
1533	    'Prov Guard —— 软件供应链证明与完整性校验工具',
1534	    '',
1535	    '用法:',
1536	    '  provguard keygen   --key-dir <dir> [--name <prefix>]',
1537	    '  provguard generate --artifact <path> --key <private.pem> --out <dir> \\',
1538	    '                      [--co-key <private.pem> ...] [--bundle]',
1539	    '  provguard verify   --artifact <path> --proof <proof.json> \\',
1540	    '                      --signature <proof.json.sig> --key <public.pem> \\',
1541	    '                      [--sbom <sbom.json> --sbom-signature <sbom.json.sig>] \\',
1542	    '                      [--cosignatures <dir> --cosigner-key <public.pem> ... \\',
1543	    '                       --min-cosigners <n>] \\',
1544	    '                      [--policy <policy.json>]',
1545	    '  provguard verify   --artifact <path> --bundle <proof.bundle.json> \\',
1546	    '                      --key <public.pem> \\',
1547	    '                      [--cosigner-key <public.pem> ... --min-cosigners <n>] \\',
1548	    '                      [--policy <policy.json>]',
1549	    '',
1550	    'generate 输出: proof.json / proof.json.sig / sbom.json / sbom.json.sig',
1551	    '启用共签时额外输出: proof.cosignatures.json / sbom.cosignatures.json',
1552	    '使用 --bundle 时额外输出: proof.bundle.json（单文件证明分发包）',
1553	    '成功状态: VERIFIED；错误码见 README。',
1554	  ].join('\n');
1555	}
1556	
1557	function printMachineError(err) {
1558	  const payload = {
1559	    status: 'ERROR',
1560	    errorCode: err instanceof ProvError ? err.code : 'INTERNAL_ERROR',
1561	    message: err && err.message ? err.message : String(err),
1562	  };
1563	  if (err && err.details !== undefined) payload.details = err.details;
1564	  return stableJsonStringify(payload);
1565	}
1566	
1567	async function main(argv) {
1568	  const args = parseArgs(argv);
1569	  const command = args._[0];
1570	
1571	  try {
1572	    if (!command || command === 'help' || command === '--help' || command === '-h') {
1573	      process.stdout.write(`${usage()}\n`);
1574	      return 0;
1575	    }
1576	
1577	    if (command === 'keygen') {
1578	      if (!args['key-dir']) {
1579	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '缺少必填参数 --key-dir');
1580	      }
1581	      const r = await keygen({ keyDir: args['key-dir'], name: args.name || 'provguard' });
1582	      process.stdout.write(
1583	        `${stableJsonStringify({ status: 'KEYGEN_OK', ...r })}\n`,
1584	      );
1585	      return 0;
1586	    }
1587	
1588	    if (command === 'generate') {
1589	      const missing = ['artifact', 'key', 'out'].filter((k) => typeof args[k] !== 'string');
1590	      if (missing.length) {
1591	        throw new ProvError(
1592	          ERROR_CODES.USAGE_ERROR,
1593	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1594	        );
1595	      }
1596	      // --co-key 可重复；出现时每个都必须带私钥路径。
1597	      const coKeys = args['co-key'] === undefined ? [] : args['co-key'];
1598	      if (coKeys.some((k) => typeof k !== 'string')) {
1599	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--co-key 需要提供共签私钥文件路径');
1600	      }
1601	      // --bundle 为开关：出现时额外写出 proof.bundle.json，不接受取值。
1602	      if (args.bundle !== undefined && args.bundle !== true) {
1603	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--bundle 是开关参数，不接受取值');
1604	      }
1605	      const r = await generate({
1606	        artifact: args.artifact,
1607	        key: args.key,
1608	        out: args.out,
1609	        coKeys,
1610	        bundle: args.bundle === true,
1611	      });
1612	      const out = {
1613	        status: 'GENERATED',
1614	        proofVersion: r.proofVersion,
1615	        artifactDigest: r.artifactDigest,
1616	        fileCount: r.fileCount,
1617	        proofPath: r.proofPath,
1618	        sbomPath: r.sbomPath,
1619	        signaturePath: r.signaturePath,
1620	        sbomSignaturePath: r.sbomSignaturePath,
1621	      };
1622	      if (r.cosignerCount !== undefined) {
1623	        out.cosignerCount = r.cosignerCount;
1624	        out.proofCosignaturesPath = r.proofCosignaturesPath;
1625	        out.sbomCosignaturesPath = r.sbomCosignaturesPath;
1626	      }
1627	      if (r.bundlePath !== undefined) {
1628	        out.bundlePath = r.bundlePath;
1629	      }
1630	      process.stdout.write(`${stableJsonStringify(out)}\n`);
1631	      return 0;
1632	    }
1633	
1634	    if (command === 'verify') {
1635	      // 包模式：--bundle 与独立文件入口（--proof/--signature/--sbom/
1636	      // --sbom-signature/--cosignatures）互斥，混用为 USAGE_ERROR。
1637	      const bundleMode = args.bundle !== undefined;
1638	      if (bundleMode && typeof args.bundle !== 'string') {
1639	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--bundle 需要提供证明分发包路径');
1640	      }
1641	      if (bundleMode) {
1642	        const conflicts = ['proof', 'signature', 'sbom', 'sbom-signature', 'cosignatures'].filter(
1643	          (k) => args[k] !== undefined,
1644	        );
1645	        if (conflicts.length) {
1646	          throw new ProvError(
1647	            ERROR_CODES.USAGE_ERROR,
1648	            `--bundle 与 ${conflicts.map((k) => `--${k}`).join('、')} 互斥`,
1649	          );
1650	        }
1651	      }
1652	      const required = bundleMode ? ['artifact', 'key'] : ['artifact', 'proof', 'signature', 'key'];
1653	      const missing = required.filter((k) => typeof args[k] !== 'string');
1654	      if (missing.length) {
1655	        throw new ProvError(
1656	          ERROR_CODES.USAGE_ERROR,
1657	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1658	        );
1659	      }
1660	      // --policy 为可选单值参数；出现时必须带文件路径。
1661	      const hasPolicy = args.policy !== undefined;
1662	      if (hasPolicy && typeof args.policy !== 'string') {
1663	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--policy 需要提供策略文件路径');
1664	      }
1665	      // --sbom 与 --sbom-signature 必须成对出现（仅独立文件模式；包模式自带 SBOM 成员）。
1666	      const hasSbom = typeof args.sbom === 'string';
1667	      const hasSbomSig = typeof args['sbom-signature'] === 'string';
1668	      if (!bundleMode && hasSbom !== hasSbomSig) {
1669	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
1670	      }
1671	      // 共签校验：独立文件模式需 --cosignatures + --cosigner-key（可重复）+ --min-cosigners；
1672	      // 包模式清单位于包内，只需 --cosigner-key + --min-cosigners。min 为不超过公钥数量的正整数。
1673	      const cosigKeysRaw = args['cosigner-key'];
1674	      const anyCosign =
1675	        args.cosignatures !== undefined || cosigKeysRaw !== undefined || args['min-cosigners'] !== undefined;
1676	      let cosignOpts = {};
1677	      if (anyCosign) {
1678	        const keyListOk =
1679	          Array.isArray(cosigKeysRaw) &&
1680	          cosigKeysRaw.length > 0 &&
1681	          cosigKeysRaw.every((k) => typeof k === 'string');
1682	        const minRaw = args['min-cosigners'];
1683	        const minOk =
1684	          typeof minRaw === 'string' && /^\d+$/.test(minRaw) && Number.isSafeInteger(Number(minRaw)) && Number(minRaw) >= 1;
1685	        const dirOk = bundleMode || typeof args.cosignatures === 'string';
1686	        if (!dirOk || !keyListOk || !minOk) {
1687	          throw new ProvError(
1688	            ERROR_CODES.USAGE_ERROR,
1689	            bundleMode
1690	              ? '--cosigner-key（可重复）与 --min-cosigners（正整数）必须同时提供'
1691	              : '--cosignatures、--cosigner-key（可重复）与 --min-cosigners（正整数）必须同时提供',
1692	          );
1693	        }
1694	        if (Number(minRaw) > cosigKeysRaw.length) {
1695	          throw new ProvError(
1696	            ERROR_CODES.USAGE_ERROR,
1697	            '--min-cosigners 超过提供的共签公钥数量',
1698	          );
1699	        }
1700	        cosignOpts = {
1701	          cosignerKeys: cosigKeysRaw,
1702	          minCosigners: Number(minRaw),
1703	        };
1704	        if (!bundleMode) cosignOpts.cosignatures = args.cosignatures;
1705	      }
1706	      const r = await verify({
1707	        artifact: args.artifact,
1708	        key: args.key,
1709	        ...(bundleMode
1710	          ? { bundle: args.bundle }
1711	          : {
1712	              proof: args.proof,
1713	              signature: args.signature,
1714	              sbom: hasSbom ? args.sbom : undefined,
1715	              sbomSignature: hasSbomSig ? args['sbom-signature'] : undefined,
1716	            }),
1717	        policy: hasPolicy ? args.policy : undefined,
1718	        ...cosignOpts,
1719	      });
1720	      process.stdout.write(`${stableJsonStringify(r)}\n`);
1721	      return 0;
1722	    }
1723	
1724	    throw new ProvError(ERROR_CODES.USAGE_ERROR, `未知子命令: ${command}`);
1725	  } catch (err) {
1726	    // stderr 仅输出机器可读 JSON；用法帮助走 stdout，避免污染错误流。
1727	    process.stderr.write(`${printMachineError(err)}\n`);
1728	    if (err instanceof ProvError && err.code === ERROR_CODES.USAGE_ERROR) {
1729	      process.stdout.write(`\n${usage()}\n`);
1730	    }
1731	    return 1;
1732	  }
1733	}
1734	
1735	// 仅作为脚本直接运行时执行 main；被测试 import 时不执行。
1736	if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
1737	  main(process.argv.slice(2)).then((code) => {
1738	    process.exitCode = code;
1739	  });
1740	}
1741	
1742	export { main, ProvError, ERROR_CODES as CODES };
1743

