893	function generateWithCoKeys(artifact, mainPriv, out, coPrivs) {
894	  const args = ['generate', '--artifact', artifact, '--key', mainPriv, '--out', out];
895	  for (const p of coPrivs) args.push('--co-key', p);
896	  const r = run(args);
897	  assert.equal(r.code, 0, JSON.stringify(r.stderr));
898	  return r.stdout;
