1135	// 修改包内某成员后回写；transform 接收解码后的字节，返回新字节。
1136	// 默认同步更新 sha256 与 size（构造“自洽但内容被改”的包）。
1137	function rewriteBundleMember(name, transform, { fixMeta = true } = {}) {
1138	  const p = join(paths.out, 'proof.bundle.json');
1139	  const b = JSON.parse(readFileSync(p, 'utf8'));
1140	  const bytes = transform(Buffer.from(b.members[name].data, 'base64'));
1141	  b.members[name].data = bytes.toString('base64');
1142	  if (fixMeta) {
1143	    b.members[name].sha256 = createHash('sha256').update(bytes).digest('hex');
1144	    b.members[name].size = bytes.length;
1145	  }
1146	  writeFileSync(p, JSON.stringify(b, null, 2) + '\n');
1147	}
