  try {
    sigOk = cryptoVerify(null, canonicalBytes, policyPublicKey, sigBuf);
  } catch {
    sigOk = false;
  }
  if (!sigOk) {
    throw new ProvError(
      ERROR_CODES.SIGNATURE_INVALID,
      '策略签名与策略内容不匹配（策略可能被改动，或签名/公钥不符）',
    );
  }
  return fingerprint;
}

