  assert.equal(verifyWithPolicySig(k.pub, p, short, k.pub).stderr.errorCode, 'SIGNATURE_INVALID');
});

test('策略、签名或策略公钥缺失 -> INPUT_NOT_FOUND', () => {
  const k = keygen(paths.keys);
