  assert.equal(
    verifyWithPolicySig(k.pub, p, join(root, 'nope.sig'), k.pub).stderr.errorCode,
    'INPUT_NOT_FOUND',
  );
  assert.equal(
    verifyWithPolicySig(k.pub, p, sig, join(root, 'nope.pem')).stderr.errorCode,
    'INPUT_NOT_FOUND',
  );
});

test('策略公钥不可解析 / 非 Ed25519 -> KEY_NOT_FOUND', () => {
